#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define STACK_MAX 64

int main(int argc, char *argv[])
{
    long stack[STACK_MAX];
    int top = 0;

    if (argc < 2) {
        puts("ERROR");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        char *tok = argv[i];
        if (strcmp(tok, "+") == 0 || strcmp(tok, "-") == 0 || strcmp(tok, "*") == 0 || strcmp(tok, "/") == 0) {
            if (top < 2) {
                puts("ERROR");
                return 0;
            }
            long b = stack[--top];
            long a = stack[--top];
            long res = 0;
            if (strcmp(tok, "+") == 0) {
                res = a + b;
            } else if (strcmp(tok, "-") == 0) {
                res = a - b;
            } else if (strcmp(tok, "*") == 0) {
                res = a * b;
            } else { // "/"
                if (b == 0) {
                    puts("ERROR");
                    return 0;
                }
                res = a / b;
            }
            if (top >= STACK_MAX) {
                puts("ERROR");
                return 0;
            }
            stack[top++] = res;
            continue;
        }
        {
            char *endptr;
            errno = 0;
            long val = strtol(tok, &endptr, 10);
            if (errno != 0 || *endptr != '\0') {
                puts("ERROR");
                return 0;
            }
            if (top >= STACK_MAX) {
                puts("ERROR");
                return 0;
            }
            stack[top++] = val;
        }
    }

    if (top != 1) {
        puts("ERROR");
        return 0;
    }

    printf("%ld\n", stack[0]);
    return 0;
}
